{
  "name": "acme-rules",
  "version": "1.0.0",
  "description": "Dynamic rule engine with a safe expression evaluator",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "test": "node test/rule-engine.test.js"
  },
  "dependencies": {
    "express": "^4.19.2"
  }
}

// Safe rule evaluator.
//
// IMPORTANT: The reference snippet in docs/RULES_ENGINE.md uses
// `Function(...)`/eval to run caller-supplied strings. That is arbitrary
// remote code execution (RCE) and must NOT be used on untrusted input.
//
// This module implements the same documented behaviour (evaluate a rule
// expression like `ctx.amount > 100` against the request context) using a
// small, sandboxed parser+evaluator that supports only safe operations:
//   - member access on the provided context (ctx.foo.bar)
//   - literals: numbers, strings ('...' / "..."), true, false, null
//   - comparisons: ==, !=, ===, !==, <, <=, >, >=
//   - boolean logic: &&, ||, !
//   - grouping with parentheses
// No function calls, no global access, no property access on prototypes.

const STRICT_PROTO_BLOCKLIST = new Set([
  '__proto__',
  'prototype',
  'constructor',
]);

// ---- Tokenizer ----
function tokenize(input) {
  const tokens = [];
  let i = 0;
  const isIdentStart = (c) => /[A-Za-z_$]/.test(c);
  const isIdentPart = (c) => /[A-Za-z0-9_$]/.test(c);

  while (i < input.length) {
    const c = input[i];

    if (/\s/.test(c)) { i++; continue; }

    // String literal
    if (c === '"' || c === "'") {
      const quote = c;
      let j = i + 1;
      let value = '';
      while (j < input.length && input[j] !== quote) {
        if (input[j] === '\\' && j + 1 < input.length) {
          value += input[j + 1];
          j += 2;
        } else {
          value += input[j];
          j++;
        }
      }
      if (j >= input.length) throw new Error('Unterminated string literal');
      tokens.push({ type: 'string', value });
      i = j + 1;
      continue;
    }

    // Number literal
    if (/[0-9]/.test(c) || (c === '.' && /[0-9]/.test(input[i + 1]))) {
      let j = i;
      while (j < input.length && /[0-9.]/.test(input[j])) j++;
      tokens.push({ type: 'number', value: Number(input.slice(i, j)) });
      i = j;
      continue;
    }

    // Identifier / keyword
    if (isIdentStart(c)) {
      let j = i;
      while (j < input.length && isIdentPart(input[j])) j++;
      tokens.push({ type: 'ident', value: input.slice(i, j) });
      i = j;
      continue;
    }

    // Multi-char operators
    const three = input.slice(i, i + 3);
    if (three === '===' || three === '!==') {
      tokens.push({ type: 'op', value: three });
      i += 3;
      continue;
    }
    const two = input.slice(i, i + 2);
    if (['==', '!=', '<=', '>=', '&&', '||'].includes(two)) {
      tokens.push({ type: 'op', value: two });
      i += 2;
      continue;
    }

    if ('<>!'.includes(c)) { tokens.push({ type: 'op', value: c }); i++; continue; }
    if (c === '(' || c === ')') { tokens.push({ type: 'paren', value: c }); i++; continue; }
    if (c === '.') { tokens.push({ type: 'dot', value: '.' }); i++; continue; }

    throw new Error(`Unexpected character '${c}' at position ${i}`);
  }
  tokens.push({ type: 'eof' });
  return tokens;
}

// ---- Parser (recursive descent) ----
// Grammar (lowest to highest precedence):
//   or   := and ('||' and)*
//   and  := not ('&&' not)*
//   not  := '!' not | cmp
//   cmp  := primary (CMP_OP primary)?
//   primary := number | string | bool | null | member | '(' or ')'
//   member := ident ('.' ident)*
const CMP_OPS = new Set(['==', '!=', '===', '!==', '<', '<=', '>', '>=']);

function parse(tokens) {
  let pos = 0;
  const peek = () => tokens[pos];
  const next = () => tokens[pos++];
  const expect = (pred, msg) => {
    const t = peek();
    if (!pred(t)) throw new Error(msg || `Unexpected token ${JSON.stringify(t)}`);
    return next();
  };

  function parseOr() {
    let left = parseAnd();
    while (peek().type === 'op' && peek().value === '||') {
      next();
      const right = parseAnd();
      left = { type: 'logical', op: '||', left, right };
    }
    return left;
  }

  function parseAnd() {
    let left = parseNot();
    while (peek().type === 'op' && peek().value === '&&') {
      next();
      const right = parseNot();
      left = { type: 'logical', op: '&&', left, right };
    }
    return left;
  }

  function parseNot() {
    if (peek().type === 'op' && peek().value === '!') {
      next();
      return { type: 'not', arg: parseNot() };
    }
    return parseCmp();
  }

  function parseCmp() {
    const left = parsePrimary();
    if (peek().type === 'op' && CMP_OPS.has(peek().value)) {
      const op = next().value;
      const right = parsePrimary();
      return { type: 'compare', op, left, right };
    }
    return left;
  }

  function parsePrimary() {
    const t = peek();
    if (t.type === 'paren' && t.value === '(') {
      next();
      const expr = parseOr();
      expect((x) => x.type === 'paren' && x.value === ')', 'Expected )');
      return expr;
    }
    if (t.type === 'number') { next(); return { type: 'literal', value: t.value }; }
    if (t.type === 'string') { next(); return { type: 'literal', value: t.value }; }
    if (t.type === 'ident') {
      if (t.value === 'true') { next(); return { type: 'literal', value: true }; }
      if (t.value === 'false') { next(); return { type: 'literal', value: false }; }
      if (t.value === 'null') { next(); return { type: 'literal', value: null }; }
      // member access chain
      const path = [next().value];
      while (peek().type === 'dot') {
        next();
        const id = expect((x) => x.type === 'ident', 'Expected identifier after .');
        path.push(id.value);
      }
      return { type: 'member', path };
    }
    throw new Error(`Unexpected token ${JSON.stringify(t)}`);
  }

  const ast = parseOr();
  expect((x) => x.type === 'eof', 'Unexpected trailing tokens');
  return ast;
}

// ---- Evaluator ----
function evaluate(ast, scope) {
  switch (ast.type) {
    case 'literal':
      return ast.value;
    case 'member': {
      let cur = scope;
      for (const key of ast.path) {
        if (STRICT_PROTO_BLOCKLIST.has(key)) {
          throw new Error(`Access to '${key}' is not allowed`);
        }
        if (cur == null) return undefined;
        // Only allow own enumerable-ish data properties, never inherited.
        if (!Object.prototype.hasOwnProperty.call(cur, key)) return undefined;
        cur = cur[key];
      }
      return cur;
    }
    case 'not':
      return !evaluate(ast.arg, scope);
    case 'logical': {
      const l = evaluate(ast.left, scope);
      if (ast.op === '&&') return l && evaluate(ast.right, scope);
      return l || evaluate(ast.right, scope);
    }
    case 'compare': {
      const l = evaluate(ast.left, scope);
      const r = evaluate(ast.right, scope);
      switch (ast.op) {
        case '==': return l == r; // eslint-disable-line eqeqeq
        case '!=': return l != r; // eslint-disable-line eqeqeq
        case '===': return l === r;
        case '!==': return l !== r;
        case '<': return l < r;
        case '<=': return l <= r;
        case '>': return l > r;
        case '>=': return l >= r;
        default: throw new Error(`Unknown operator ${ast.op}`);
      }
    }
    default:
      throw new Error(`Unknown node type ${ast.type}`);
  }
}

/**
 * Safely evaluate a rule expression against a context object.
 * @param {string} expr  e.g. "ctx.amount > 100 && ctx.country === 'US'"
 * @param {object} context  data the rule is evaluated against
 * @returns {boolean} coerced result of the expression
 */
function evalRule(expr, context) {
  if (typeof expr !== 'string') {
    throw new Error('rule must be a string');
  }
  if (expr.length > 2000) {
    throw new Error('rule expression too long');
  }
  const ast = parse(tokenize(expr));
  const scope = { ctx: context || {} };
  return Boolean(evaluate(ast, scope));
}

module.exports = { evalRule, tokenize, parse, evaluate };

