// (./ruleEngine) that supports the documented expression behaviour safely.
app.post('/check', (req, res) => {
  const { rule, context } = req.body || {};

  if (typeof rule !== 'string' || rule.trim() === '') {
    return res.status(400).json({ error: 'Field "rule" (non-empty string) is required.' });
  }
  if (context !== undefined && (typeof context !== 'object' || context === null || Array.isArray(context))) {
    return res.status(400).json({ error: 'Field "context" must be an object when provided.' });
  }

