const assert = require('assert');
const { evalRule } = require('../ruleEngine');

// Documented happy paths
assert.strictEqual(evalRule('ctx.amount > 100', { amount: 150 }), true);
assert.strictEqual(evalRule('ctx.amount > 100', { amount: 50 }), false);
assert.strictEqual(evalRule("ctx.country === 'US'", { country: 'US' }), true);
assert.strictEqual(evalRule('ctx.amount > 100 && ctx.vip', { amount: 200, vip: true }), true);
assert.strictEqual(evalRule('ctx.amount > 100 || ctx.vip', { amount: 5, vip: true }), true);
assert.strictEqual(evalRule('!ctx.blocked', { blocked: false }), true);
assert.strictEqual(evalRule('ctx.user.age >= 18', { user: { age: 21 } }), true);
assert.strictEqual(evalRule('(ctx.a < 5) || (ctx.b == 2)', { a: 9, b: 2 }), true);

// Security: no code execution / no prototype escape
const evil = [
  "ctx.constructor.constructor('return process')()",
  "ctx.__proto__",
  "require('child_process')",
  "process.env",
  "global",
  "this",
  "ctx.constructor",
];
for (const expr of evil) {
  let threwOrFalse = false;
  try {
    const r = evalRule(expr, {});
    // Must not return anything dangerous; any truthy object access is blocked.
    threwOrFalse = (r === false || r === true);
    // Ensure we never got a function/process back.
    assert.notStrictEqual(typeof r, 'function');
  } catch (e) {
    threwOrFalse = true;
  }
  assert.ok(threwOrFalse, `expression should be safely handled: ${expr}`);
}

console.log('All rule engine tests passed.');

