// --- Safe rule evaluation ---
//
// NOTE: The reference implementation in docs/RULES_ENGINE.md evaluates the
// caller-supplied `rule` string with `Function(...)` / dynamic eval. That is a
// remote code execution (RCE) vulnerability: any client could run arbitrary
// JavaScript on the server (read files, env vars, exfiltrate data, etc.).
// We deliberately do NOT use that approach.
//
// Instead we support a small, safe expression grammar that covers the
// documented use case (e.g. "ctx.amount > 100") without executing arbitrary
// code. Expressions may reference `ctx.<field>` paths, literals (numbers,
// quoted strings, true/false/null), comparison operators, and && / || / ().

const COMPARATORS = {
  '===': (a, b) => a === b,
  '!==': (a, b) => a !== b,
  '==': (a, b) => a == b, // eslint-disable-line eqeqeq
  '!=': (a, b) => a != b, // eslint-disable-line eqeqeq
  '>=': (a, b) => a >= b,
  '<=': (a, b) => a <= b,
  '>': (a, b) => a > b,
  '<': (a, b) => a < b,
};

function tokenize(expr) {
  const tokens = [];
  const re = /\s*(&&|\|\||===|!==|==|!=|>=|<=|>|<|\(|\)|"(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|[A-Za-z_$][\w$.]*|-?\d+(?:\.\d+)?)/y;
  let pos = 0;
  while (pos < expr.length) {
    re.lastIndex = pos;
    const m = re.exec(expr);
    if (!m || m.index !== pos) {
      // allow trailing whitespace
      if (/^\s*$/.test(expr.slice(pos))) break;
      throw new Error(`Unexpected token at: "${expr.slice(pos)}"`);
    }
    tokens.push(m[1]);
    pos = re.lastIndex;
  }
  return tokens;
}

function resolvePath(path, ctx) {
  // Only resolve identifiers rooted at `ctx`. Anything else is rejected so
  // callers cannot reach globals, process, require, etc.
  const parts = path.split('.');
  if (parts[0] !== 'ctx') {
    throw new Error(`Disallowed identifier: "${path}" (only ctx.* is allowed)`);
  }
  let value = ctx;
  for (let i = 1; i < parts.length; i++) {
    if (value == null) return undefined;
    value = value[parts[i]];
  }
  return value;
}

function literalValue(token, ctx) {
  if (token === 'true') return true;
  if (token === 'false') return false;
  if (token === 'null') return null;
  if (/^-?\d+(?:\.\d+)?$/.test(token)) return Number(token);
  if (
    (token.startsWith('"') && token.endsWith('"')) ||
    (token.startsWith("'") && token.endsWith("'"))
  ) {
    return JSON.parse(token.startsWith("'") ? `"${token.slice(1, -1).replace(/"/g, '\\"')}"` : token);
  }
  if (/^[A-Za-z_$][\w$.]*$/.test(token)) return resolvePath(token, ctx);
  throw new Error(`Invalid operand: "${token}"`);
}

// Recursive-descent parser: expr := or; or := and ('||' and)*;
// and := comparison ('&&' comparison)*; comparison := primary (op primary)?;
// primary := '(' expr ')' | literal/identifier
function evaluate(tokens, ctx) {
  let i = 0;
  const peek = () => tokens[i];
  const next = () => tokens[i++];

  function parsePrimary() {
    if (peek() === '(') {
      next();
      const v = parseOr();
      if (next() !== ')') throw new Error('Expected ")"');
      return v;
    }
    const tok = next();
    if (tok === undefined) throw new Error('Unexpected end of expression');
    return literalValue(tok, ctx);
  }

  function parseComparison() {
    const left = parsePrimary();
    const op = peek();
    if (COMPARATORS[op]) {
      next();
      const right = parsePrimary();
      return COMPARATORS[op](left, right);
    }
    return left;
  }

  function parseAnd() {
    let v = parseComparison();
    while (peek() === '&&') {
      next();
      const r = parseComparison();
      v = v && r;
    }
    return v;
  }

  function parseOr() {
    let v = parseAnd();
    while (peek() === '||') {
      next();
      const r = parseAnd();
      v = v || r;
    }
    return v;
  }

  const result = parseOr();
  if (i < tokens.length) throw new Error(`Unexpected token: "${tokens[i]}"`);
  return result;
