// Safe rule evaluator.
//
// Evaluates boolean/comparison expressions referencing `ctx` WITHOUT using
// eval/Function. Supports:
//   - literals: numbers, single/double-quoted strings, true, false, null
//   - identifiers: ctx and dotted paths like ctx.amount, ctx.user.role
//   - comparisons: == != === !== < <= > >=
//   - logic: && || ! and parentheses
//   - arithmetic: + - * / %
//
// It does NOT support function calls, member access on arbitrary globals,
// assignment, or any side-effecting constructs. This makes it safe to run on
// untrusted input.

const TOKEN_RE =
  /\s*(=>|===|!==|==|!=|<=|>=|&&|\|\||[<>()!+\-*/%.]|true\b|false\b|null\b|[A-Za-z_$][A-Za-z0-9_$]*|\d+(?:\.\d+)?|"(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*')/y;

function tokenize(src) {
  const tokens = [];
  TOKEN_RE.lastIndex = 0;
  let pos = 0;
  while (pos < src.length) {
    // skip leading whitespace only between tokens
    if (/\s/.test(src[pos])) {
      pos++;
      continue;
    }
    TOKEN_RE.lastIndex = pos;
    const m = TOKEN_RE.exec(src);
    if (!m || m.index !== pos) {
      throw new Error(`Unexpected token at position ${pos}: "${src.slice(pos, pos + 10)}"`);
    }
    const value = m[1];
    tokens.push(value);
    pos = TOKEN_RE.lastIndex;
  }
  return tokens;
}

// Recursive-descent parser -> AST.
function parse(tokens) {
  let i = 0;
  const peek = () => tokens[i];
  const next = () => tokens[i++];
  const expect = (t) => {
    if (tokens[i] !== t) throw new Error(`Expected "${t}" but got "${tokens[i] ?? 'end of input'}"`);
    i++;
  };

  function parseOr() {
    let node = parseAnd();
    while (peek() === '||') {
      next();
      node = { type: 'logic', op: '||', left: node, right: parseAnd() };
    }
    return node;
  }
  function parseAnd() {
    let node = parseEquality();
    while (peek() === '&&') {
      next();
      node = { type: 'logic', op: '&&', left: node, right: parseEquality() };
    }
    return node;
  }
  function parseEquality() {
    let node = parseComparison();
    while (['==', '!=', '===', '!=='].includes(peek())) {
      const op = next();
      node = { type: 'binary', op, left: node, right: parseComparison() };
    }
    return node;
  }
  function parseComparison() {
    let node = parseAdditive();
    while (['<', '<=', '>', '>='].includes(peek())) {
      const op = next();
      node = { type: 'binary', op, left: node, right: parseAdditive() };
    }
    return node;
  }
