    let node = parseMultiplicative();
    while (['+', '-'].includes(peek())) {
      const op = next();
      node = { type: 'binary', op, left: node, right: parseMultiplicative() };
    }
    return node;
  }
  function parseMultiplicative() {
    let node = parseUnary();
    while (['*', '/', '%'].includes(peek())) {
      const op = next();
      node = { type: 'binary', op, left: node, right: parseUnary() };
    }
    return node;
  }
  function parseUnary() {
    if (peek() === '!') {
      next();
      return { type: 'unary', op: '!', arg: parseUnary() };
    }
    if (peek() === '-') {
      next();
      return { type: 'unary', op: '-', arg: parseUnary() };
    }
    return parsePrimary();
  }
  function parsePrimary() {
    const t = peek();
    if (t === '(') {
      next();
      const node = parseOr();
      expect(')');
      return node;
    }
    if (t === 'true' || t === 'false') {
      next();
      return { type: 'literal', value: t === 'true' };
    }
    if (t === 'null') {
      next();
      return { type: 'literal', value: null };
    }
    if (/^\d/.test(t)) {
      next();
      return { type: 'literal', value: Number(t) };
    }
    if (/^["']/.test(t)) {
      next();
      return { type: 'literal', value: JSON.parse(/^'/.test(t) ? `"${t.slice(1, -1).replace(/"/g, '\\"')}"` : t) };
