      const path = [next()];
      while (peek() === '.') {
        next();
        const prop = next();
        if (!/^[A-Za-z_$][A-Za-z0-9_$]*$/.test(prop || '')) {
          throw new Error(`Invalid property name "${prop}"`);
        }
        path.push(prop);
      }
      return { type: 'path', path };
    }
    throw new Error(`Unexpected token "${t ?? 'end of input'}"`);
  }

