}

// Disallow reaching into prototype/dangerous keys.
const BLOCKED_KEYS = new Set(['__proto__', 'prototype', 'constructor']);

function resolvePath(path, scope) {
  if (path[0] !== 'ctx') {
    throw new Error(`Unknown identifier "${path[0]}" (only "ctx" is allowed)`);
  }
