      switch (node.op) {
        case '==': return l == r; // eslint-disable-line eqeqeq
        case '!=': return l != r; // eslint-disable-line eqeqeq
        case '===': return l === r;
        case '!==': return l !== r;
        case '<': return l < r;
        case '<=': return l <= r;
        case '>': return l > r;
        case '>=': return l >= r;
        case '+': return l + r;
        case '-': return l - r;
        case '*': return l * r;
        case '/': return l / r;
        case '%': return l % r;
        default: throw new Error(`Unsupported operator "${node.op}"`);
      }
    }
    default:
      throw new Error(`Unsupported node type "${node.type}"`);
  }
}

function evalRule(expr, ctx) {
  const tokens = tokenize(expr);
  const ast = parse(tokens);
  return evaluate(ast, { ctx });
}

module.exports = { evalRule, tokenize, parse };

